def compute(vars):
    total_net_derivatives = vars["v1"]
    foreign_exchange_hedges = vars["v2"]
    value = total_net_derivatives - foreign_exchange_hedges
    return {
        "value": value,
        "trace": {
            "v1": total_net_derivatives,
            "v2": foreign_exchange_hedges,
            "operation": "v1 - v2",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
